package protocol

type ProfileBinding struct {
	Project                 string `json:"project"`
	Profile                 string `json:"profile"`
	Owner                   string `json:"owner"`
	InstanceID              string `json:"instanceID"`
	BinarySHA256            string `json:"binarySHA256"`
	ConfigSHA256            string `json:"configSHA256"`
	FixtureSHA256           string `json:"fixtureSHA256"`
	ProfileContractIdentity string `json:"profileContractIdentity"`
	ProfileConfigSHA256     string `json:"profileConfigSHA256"`
}
type ProfileClock struct {
	Instant    string `json:"instant"`
	Generation string `json:"generation"`
	InstanceID string `json:"instanceID"`
	Source     string `json:"source"`
	Healthy    bool   `json:"healthy"`
}
type ProfileSession struct {
	SessionID         string `json:"sessionID"`
	DigestProof       string `json:"digestProof"`
	CreatedAt         string `json:"createdAt"`
	IdleExpiresAt     string `json:"idleExpiresAt"`
	AbsoluteExpiresAt string `json:"absoluteExpiresAt"`
	RememberMe        bool   `json:"rememberMe"`
	CredentialVersion string `json:"credentialVersion"`
}
type ProfileAuthFacts struct {
	Phase                string           `json:"phase"`
	Revision             string           `json:"revision"`
	UserID               string           `json:"userID"`
	VerifierProof        string           `json:"verifierProof"`
	Sessions             []ProfileSession `json:"sessions"`
	TimeZone             string           `json:"timeZone"`
	SettingsVersion      string           `json:"settingsVersion"`
	CommandFactsSHA256   string           `json:"commandFactsSHA256"`
	TombstoneFactsSHA256 string           `json:"tombstoneFactsSHA256"`
	CredentialVersion    string           `json:"credentialVersion"`
	Login                string           `json:"login"`
	DisplayName          string           `json:"displayName"`
	OrgID                string           `json:"orgID"`
	RestaurantID         string           `json:"restaurantID"`
	MembershipID         string           `json:"membershipID"`
}
type ProfileRotation struct {
	ActiveKID    string   `json:"activeKID"`
	NextKID      *string  `json:"nextKID"`
	PreviousKID  *string  `json:"previousKID"`
	PublishedAt  *string  `json:"publishedAt"`
	LastIssuedAt *string  `json:"lastIssuedAt"`
	RetainUntil  *string  `json:"retainUntil"`
	JWKSKIDs     []string `json:"jwksKIDs"`
	JWKSRequests struct {
		Gateway   int `json:"gateway"`
		Warehouse int `json:"warehouse"`
		Serving   int `json:"serving"`
	} `json:"jwksRequests"`
	Result string `json:"result"`
}
type ProfileWriter struct {
	Attempts        int    `json:"attempts"`
	PrimaryLockHeld bool   `json:"primaryLockHeld"`
	PrimaryReady    bool   `json:"primaryReady"`
	ChildOpened     bool   `json:"childOpened"`
	ChildReady      bool   `json:"childReady"`
	ChildError      string `json:"childError"`
	Writers         int    `json:"writers"`
	SameOwnedVolume bool   `json:"sameOwnedVolume"`
	ChildExitCode   int    `json:"childExitCode"`
}
type ProfileAuthLegacy struct {
	SchemaVersion   int                          `json:"schemaVersion"`
	Identity        ProfileAuthIdentityMap       `json:"identity"`
	VerifierProof   string                       `json:"verifierProof"`
	Sessions        []ProfileAuthPreparedSession `json:"sessions"`
	SessionMap      []ProfileAuthSessionMap      `json:"sessionMap"`
	TimeZone        string                       `json:"timeZone"`
	SettingsVersion string                       `json:"settingsVersion"`
	PreparedClock   ProfileClock                 `json:"preparedClock"`
}
type ProfileRequest struct {
	Amendment          string `json:"amendment"`
	Project            string `json:"project"`
	Profile            string `json:"profile"`
	RequestID          string `json:"requestID"`
	ExpectedInstanceID string `json:"expectedInstanceID"`
	ExpectedGeneration string `json:"expectedGeneration"`
	Action             string `json:"action"`
}
type ProfileProfileConfig struct {
	Amendment               string `json:"amendment"`
	Project                 string `json:"project"`
	Profile                 string `json:"profile"`
	ProfileContractIdentity string `json:"profileContractIdentity"`
}
type ProfileProfileError struct {
	Amendment string `json:"amendment"`
	RequestID string `json:"requestID"`
	Error     string `json:"error"`
}
type ProfileAuthPreparedSession struct {
	DigestProof       string `json:"digestProof"`
	CreatedAt         string `json:"createdAt"`
	LastSeenAt        string `json:"lastSeenAt"`
	ExpiresAt         string `json:"expiresAt"`
	RememberMe        bool   `json:"rememberMe"`
	CredentialVersion string `json:"credentialVersion"`
}
type ProfileAuthIdentityMap struct {
	OldProfileID         string `json:"oldProfileID"`
	OldLogin             string `json:"oldLogin"`
	OldDisplayName       string `json:"oldDisplayName"`
	OldCredentialVersion string `json:"oldCredentialVersion"`
	UserID               string `json:"userID"`
	OrgID                string `json:"orgID"`
	RestaurantID         string `json:"restaurantID"`
	MembershipID         string `json:"membershipID"`
}
type ProfileAuthSessionMap struct {
	DigestProof string `json:"digestProof"`
	SessionID   string `json:"sessionID"`
}
type ProfileCatalogRequest struct {
	Amendment          string `json:"amendment"`
	Project            string `json:"project"`
	RequestID          string `json:"requestID"`
	ExpectedInstanceID string `json:"expectedInstanceID"`
	ExpectedGeneration string `json:"expectedGeneration"`
	Action             string `json:"action"`
}
type ProfileCatalogFact struct {
	Owner            string `json:"owner"`
	Version          string `json:"version"`
	ArchiveSHA256    string `json:"archiveSHA256"`
	ArchiveBytes     int    `json:"archiveBytes"`
	BuildToolchain   string `json:"buildToolchain"`
	Ready            bool   `json:"ready"`
	ProvenanceSHA256 string `json:"provenanceSHA256"`
}
type ProfileCatalogReport struct {
	Amendment    string             `json:"amendment"`
	RequestID    string             `json:"requestID"`
	Project      string             `json:"project"`
	InstanceID   string             `json:"instanceID"`
	Clock        ProfileClock       `json:"clock"`
	BinarySHA256 string             `json:"binarySHA256"`
	ConfigSHA256 string             `json:"configSHA256"`
	Catalog      ProfileCatalogFact `json:"catalog"`
}
type ProfileReport struct {
	Amendment              string         `json:"amendment"`
	RequestID              string         `json:"requestID"`
	Binding                ProfileBinding `json:"binding"`
	Clock                  ProfileClock   `json:"clock"`
	Admission              string         `json:"admission"`
	NormalReady            bool           `json:"normalReady"`
	BusinessHandlerCreated bool           `json:"businessHandlerCreated"`
	Error                  *string        `json:"error"`
	Facts                  ProfileFacts   `json:"facts"`
}
type ProfileFacts struct {
	Auth     *ProfileAuthFacts  `json:"auth,omitempty"`
	Legacy   *ProfileAuthLegacy `json:"legacy,omitempty"`
	Rotation *ProfileRotation   `json:"rotation,omitempty"`
	Writer   *ProfileWriter     `json:"writer,omitempty"`
}

